proof fn always_double_equality<T>(p: TempPred<T>)
    ensures always(always(p)) == always(p),
{
    let a: TempPred<T> = always(p);
    let b: TempPred<T> = always(a);

    // Show b.entails(a)
    assert(b.entails(a)) by {
        assert(valid(b.implies(a))) by {
            assert(forall |ex: Execution<T>| b.implies(a).satisfied_by(ex)) by {
                forall |ex: Execution<T>| {
                    if b.satisfied_by(ex) {
                        // b.implies(a).satisfied_by(ex) is b.satisfied_by(ex) ==> a.satisfied_by(ex)
                        assert(a.satisfied_by(ex));
                    }
                }
            };
        };
    };

    // Show a.entails(b)
    assert(a.entails(b)) by {
        assert(valid(a.implies(b))) by {
            assert(forall |ex: Execution<T>| a.implies(b).satisfied_by(ex)) by {
                forall |ex: Execution<T>| {
                    if a.satisfied_by(ex) {
                        assert(b.satisfied_by(ex));
                    }
                }
            };
        };
    };

    temp_pred_equality(b, a);
}

