                                    // From b.satisfied_by(ex), get a.satisfied_by(ex.suffix(0))
                                    assert(a.satisfied_by(ex.suffix(0)));
                                    // Then from that, get p.satisfied_by((ex.suffix(0)).suffix(k))
                                    assert(p.satisfied_by((ex.suffix(0)).suffix(k)));

                                    // And rewrite ((ex.suffix(0)).suffix(k)) to ex.suffix(k)
                                    execution_suffix_add(ex, 0, k);
                                    assert(p.satisfied_by(ex.suffix(k)));
                                };
                            };
                        };
                    };
                }
            };
        };
    };

    // Prove a.entails(b)
    assert(a.entails(b)) by {
        assert(valid(a.implies(b))) by {
            assert(forall |ex: Execution<T>| a.implies(b).satisfied_by(ex)) by {
                forall |ex: Execution<T>| {
                    if a.satisfied_by(ex) {
                        assert(b.satisfied_by(ex)) by {
                            assert(forall |i: nat| #[trigger] a.satisfied_by(ex.suffix(i))) by {
                                forall |i: nat| {
                                    assert(a.satisfied_by(ex.suffix(i))) by {
                                        assert(forall |k: nat| #[trigger] p.satisfied_by((ex.suffix(i)).suffix(k))) by {
                                            forall |k: nat| {
                                                // a.satisfied_by(ex) gives p.satisfied_by(ex.suffix(i+k))
                                                assert(p.satisfied_by(ex.suffix(i + k)));

                                                // Rewrite ex.suffix(i).suffix(k) to ex.suffix(i+k)
                                                execution_suffix_add(ex, i, k);
                                                assert(p.satisfied_by((ex.suffix(i)).suffix(k)));
                                            };
                                        };
                                    };
                                };
                            };
                        };
                    };
                }
            };
        };
    };

    temp_pred_equality(b, a);
}

